-- Native structural acceptance; lifecycle fixtures run separately and roll back.
DO $assertions$
DECLARE f record;
BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='celebix_saas_support_runtime' AND (rolcanlogin OR rolinherit OR rolbypassrls OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN RAISE EXCEPTION 'SUPPORT_ROLE_ESCALATION'; END IF;
 IF has_table_privilege('celebix_saas_support_runtime','saas.platform_support_sessions','SELECT') OR has_function_privilege('celebix_saas_app','saas.platform_support_issue(uuid,uuid,text,text,bigint,text,text)','EXECUTE') THEN RAISE EXCEPTION 'SUPPORT_PRIVILEGES_OPEN'; END IF;
 IF has_table_privilege('celebix_saas_app','saas.platform_provenance_memberships','SELECT') OR has_table_privilege('celebix_saas_support_runtime','saas.platform_provenance_memberships','SELECT') THEN RAISE EXCEPTION 'SUPPORT_PROVENANCE_VIEW_OPEN'; END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='saas' AND p.prokind='f' AND p.proname NOT LIKE 'platform_%' AND p.prosrc~*'(FROM|JOIN)[[:space:]]+saas.memberships([[:space:]]|$)') THEN RAISE EXCEPTION 'UNHARDENED_MEMBERSHIP_AUTHORITY'; END IF;
 FOR f IN SELECT p.proname,p.prosrc FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='saas' AND (p.proname IN ('in_store_sales_mutate','in_store_sales_mutate_v2','in_store_sales_mutate_v3') OR p.proname LIKE 'public_checkout_complete%' AND p.prosrc LIKE '%INSERT INTO saas.orders%' OR p.proname LIKE 'public_storefront_hosted_checkout_begin%' AND p.prosrc LIKE '%INSERT INTO saas.storefront_hosted_checkout_sessions%') LOOP IF f.prosrc NOT LIKE '%platform_new_sales_allowed%' THEN RAISE EXCEPTION 'MISSING_NEW_ADMISSION_GUARD %',f.proname; END IF; END LOOP;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='saas' AND p.prokind='f' AND p.proname NOT LIKE 'platform_%' AND p.provolatile='v' AND p.proargnames && ARRAY['p_membership_id','p_membership','p_member']::text[] AND p.proargnames && ARRAY['p_store_id','p_store']::text[] AND p.proargnames && ARRAY['p_principal_id','p_principal']::text[] AND p.prosrc~*'(INSERT INTO|UPDATE saas.|DELETE FROM)' AND p.prosrc NOT LIKE '%platform_support_begin%') THEN RAISE EXCEPTION 'UNJOURNALED_SUPPORT_MUTATION'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='saas' AND c.relkind='r' AND c.relname NOT LIKE 'platform_%' AND c.relname<>'store_sales_policy' AND c.relowner='celebix_saas_owner'::regrole AND NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=c.oid AND t.tgname='platform_support_atomic_journal')) THEN RAISE EXCEPTION 'MISSING_ATOMIC_SUPPORT_JOURNAL'; END IF;
END $assertions$;
